import{at as e,it as t,n,vt as r}from"./chunks/framework.CinQa4et.js";var i=JSON.parse(`{"title":"JevSenseとは","description":"","frontmatter":{},"headers":[],"relativePath":"introduction/overview.md","filePath":"introduction/overview.md","lastUpdated":1793464466000}`),a={name:`introduction/overview.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="jevsenseとは" tabindex="-1">JevSenseとは <a class="header-anchor" href="#jevsenseとは" aria-label="Permalink to “JevSenseとは”">​</a></h1><p>JevSenseは、訪問者の閲覧から関心や状態を判定し、用意した案内を適切な場面で表示するWebパーソナライズ基盤です。自分のCloudflareまたはNode.js環境で運用します。</p><h2 id="向いている使い方" tabindex="-1">向いている使い方 <a class="header-anchor" href="#向いている使い方" aria-label="Permalink to “向いている使い方”">​</a></h2><table tabindex="0"><thead><tr><th>サイト</th><th>たとえば</th></tr></thead><tbody><tr><td>EC</td><td>機能性ウェアに関心のある人へ、特集ページを案内する</td></tr><tr><td>BtoB</td><td>導入や運用に関心のある人へ、導入ガイドを紹介する</td></tr><tr><td>メディア</td><td>特定のテーマを続けて読んでいる人へ、関連記事を案内する</td></tr><tr><td>採用</td><td>開発環境に関心のある人へ、エンジニア向けイベントを紹介する</td></tr><tr><td>教育</td><td>学習の進め方に関心のある人へ、説明会を案内する</td></tr><tr><td>予約サービス</td><td>利用プランを検討している人へ、相談窓口を案内する</td></tr></tbody></table><p>表示する文章・画像・リンク・JavaScriptは、管理者が事前に用意します。</p><h2 id="判断はどのように行うか" tabindex="-1">判断はどのように行うか <a class="header-anchor" href="#判断はどのように行うか" aria-label="Permalink to “判断はどのように行うか”">​</a></h2><ol><li>共通SDKが、同意後に閲覧順序・表示時間・ページ情報を観測します。</li><li>判断が必要なタイミングで、必要な情報を自前APIへ送ります。</li><li>APIが有効な閲覧を選び、Jevへstateと独立したYes/No質問を送ります。</li><li>コードが閾値・AND/OR・対象ページ・表示回数などを確認し、登録済みのコンテンツを返します。</li><li>SDKがページ上に表示します。</li></ol><h2 id="生成aiとの違い" tabindex="-1">生成AIとの違い <a class="header-anchor" href="#生成aiとの違い" aria-label="Permalink to “生成AIとの違い”">​</a></h2><p>Jevは対象者を判断するために使います。文章・画像・HTMLの生成には使いません。管理画面の入力支援も、入力した文を固定の質問テンプレートへ当てはめる処理です。</p><p>判定値は「この関心・状態が当てはまるか」の判断材料です。購入率・施策効果・将来の行動の保証ではありません。</p><h2 id="担当者ごとの入口" tabindex="-1">担当者ごとの入口 <a class="header-anchor" href="#担当者ごとの入口" aria-label="Permalink to “担当者ごとの入口”">​</a></h2><p><strong>施策を作る方</strong>は、管理者から招待を受けて<a href="./../guides/accounts">アカウント</a>を登録し、<a href="./../guides/campaigns">施策を作成</a>します。開発環境のインストールは不要です。</p><p><strong>導入する方</strong>は、<a href="./../getting-started/cloudflare">Cloudflare</a>または<a href="./../getting-started/node">Node.js</a>をセットアップし、<a href="./../integration/sdk">SDKタグ</a>を設置します。</p><p><strong>運用する方</strong>は、<a href="./../operations/security">権限・秘密情報</a>、<a href="./../operations/maintenance">更新と復旧</a>を確認してください。</p><h2 id="保存するデータ" tabindex="-1">保存するデータ <a class="header-anchor" href="#保存するデータ" aria-label="Permalink to “保存するデータ”">​</a></h2><p>閲覧者の履歴と表示済み状態はブラウザ内に持ちます。サーバーへ閲覧者ID・閲覧者セッション・行動履歴DBは追加しません。</p><p>管理者のアカウント・パスキー公開鍵・所属・施策設定は管理用DBへ保存します。外部送信がないという意味ではないので、<a href="./../integration/data">取得・送信データ</a>も確認してください。</p>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};